import React, { useEffect, useState, useRef } from 'react';
import { FaPlane } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';
import { createNoise2D } from 'simplex-noise';

const DecorativePlanes = () => {
  const { theme } = useTheme();
  const [planes, setPlanes] = useState([]);
  const noise2D = useRef(createNoise2D());
  const frameRef = useRef(0);
  const animationFrameRef = useRef();

  const createPlane = (id) => ({
    id,
    size: 8 + Math.random() * 10,
    angle: Math.random() * Math.PI * 2,
    speed: 0.7 + Math.random() * 1.5,
    noiseSeed: Math.random() * 1000,
    turnStrength: 0.03 + Math.random() * 0.07,
    noiseTimeFactor: 0.005,
    x: Math.random() < 0.25 
      ? (() => {
          const edge = Math.floor(Math.random() * 4);
          if (edge === 0) return { x: Math.random() * 100, y: -8 };
          if (edge === 1) return { x: Math.random() * 100, y: 108 };
          if (edge === 2) return { x: -8, y: Math.random() * 100 };
          return { x: 108, y: Math.random() * 100 };
        })()
      : { x: Math.random() * 100, y: Math.random() * 100 }
  });

  const updatePlane = (plane) => {
    const time = frameRef.current * plane.noiseTimeFactor;
    const angleChange = (noise2D.current(plane.noiseSeed + time, 0) - 0.5) * 2 * plane.turnStrength;
    const newAngle = plane.angle + angleChange;
    
    const newX = plane.x + Math.cos(newAngle) * plane.speed;
    const newY = plane.y + Math.sin(newAngle) * plane.speed;

    // Screen wrapping
    const wrappedX = newX < -plane.size ? 100 + plane.size : 
                    newX > 100 + plane.size ? -plane.size : newX;
    const wrappedY = newY < -plane.size ? 100 + plane.size : 
                    newY > 100 + plane.size ? -plane.size : newY;

    return {
      ...plane,
      angle: newAngle,
      x: wrappedX,
      y: wrappedY
    };
  };

  useEffect(() => {
    // Initialize planes
    const initialPlanes = Array.from({ length: 15 }, (_, index) => createPlane(index));
    setPlanes(initialPlanes);

    // Animation loop
    const animate = () => {
      frameRef.current++;
      setPlanes(currentPlanes => 
        currentPlanes.map(plane => updatePlane(plane))
      );
      animationFrameRef.current = requestAnimationFrame(animate);
    };

    animationFrameRef.current = requestAnimationFrame(animate);

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, []);

  return (
    <div className="fixed inset-0 pointer-events-none overflow-hidden" style={{ zIndex: 0 }}>
      {planes.map(plane => (
        <div
          key={plane.id}
          className="absolute"
          style={{
            left: `${plane.x}%`,
            top: `${plane.y}%`,
            transform: `rotate(${plane.angle * (180 / Math.PI)}deg)`,
            transition: 'transform 0.1s linear',
            opacity: 0.3,
            color: theme.primary
          }}
        >
          <FaPlane size={plane.size} />
        </div>
      ))}
    </div>
  );
};

export default DecorativePlanes;
